63	function getDisplayTitle(job: PastJob): string {
64	  if (job.title) return job.title;
65	  const firstLine = job.job_description.trim().split("\n")[0].trim();
66	  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
67	}
68	
69	const JobSidebar = ({ pastJobs, selectedJobId, showDashboard, loadingPastJobs, onSelectJob, onNewJob, onDashboard, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
70	  const [search, setSearch] = useState("");
71	  const [editingId, setEditingId] = useState<string | null>(null);
72	  const [editValue, setEditValue] = useState("");
73	  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
74	  const editInputRef = useRef<HTMLInputElement>(null);
75	
76	  const filteredJobs = useMemo(() => {
77	    if (!search.trim()) return pastJobs;
78	    const q = search.toLowerCase();
79	    return pastJobs.filter(
